classDiagram
  class Preview {
    +PathBuf path
    +DisplayMode mode
    +render(width) Lines
  }
  class Renderer {
    +draw(source) Svg
  }
  class MermaidRenderer {
    +DiagramKind kind
    +draw(source) Svg
  }
  Preview --> Renderer : 委譲する
  Renderer <|-- MermaidRenderer

erDiagram
  TAB["タブ"] {
    int index PK
    string root
    string cursor
  }
  MARK["ブックマーク"] {
    string key PK
    string path
  }
  ROOT["ルート"] {
    string path PK
  }
  TAB ||--|| ROOT : 起点にする
  TAB ||--o{ MARK : 覚える

zenuml
  title ファイルを開く
  @Actor You
  You->konoma: Enter
  konoma->Resolver.resolve(path) {
    return kind
  }
  if(kind == "image") {
    konoma->Decoder: 復号する
  } else {
    konoma->Window: 1 画面ぶん読む
  }
  konoma->You: 全画面プレビュー

requirementDiagram
  requirement 描画は止まらない {
    id: 1
    text: 再描画は必ず 60ms 以内に終わる
    risk: high
    verifymethod: test
  }
  element 速度テスト {
    type: simulation
  }
  速度テスト - verifies -> 描画は止まらない

radar-beta
  title 端末にできること
  axis img["画像"], vid["動画"], spd["速度"], col["色"]
  curve k["kitty graphics"]{5, 5, 5, 4}
  curve s["sixel"]{4, 3, 3, 4}
  curve h["ハーフブロック"]{2, 2, 4, 3}
  max 5
  min 0
